#!/bin/zsh
# 让 Codex 出「做成视频 → 我的主播」的设计图：不带默认人物，主播由用户自己上传照片添加。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "请使用内置的 image_gen 工具生成一张高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视、纯浅灰背景上只放这一个窗口）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="这是 macOS 桌面应用「豆仓」里的一个弹出单（sheet），宽约 620。豆仓把录音整理成文字，这个弹出单是把一篇口播稿「做成数字人视频」。设计语言：苹果 macOS 最新系统的风格加乔纳森·艾维式的克制——圆角卡片、细分隔线、说明文字是小号灰字、对齐严谨、留白舒服。配色严格限定：暖灰纸色背景（#FAF9F7）、卡片是纯白、深暖灰文字（#1C1917）、唯一强调色玫瑰红（#F43F5E，用在主按钮、选中描边和选中的分段）；绝对不要蓝色、紫色、青色、琥珀色。人物照片都是虚构的普通亚洲人，写实但只占小缩略图。界面文字全部是简体中文，字体像苹方，文字清晰可读、没有乱码。"
gen ui_hosts_empty "【还没有主播的状态】弹出单从上到下：标题「做成视频」和一行小灰字「把这篇口播稿交给 Claude 桌面版，用 Renoise 生成带包装的数字人视频」；「包装风格」三张并排小卡片「高级 · 网感」「高级 · 克制」「综艺花字」，第一张有玫瑰红描边；一行「比例」右边分段选择「9:16 竖屏」「16:9 横屏」。然后是「主播」区域：一张虚线描边的大空状态卡片，中间一个线条风格的人像加号图标，粗体「还没有主播」，小灰字「上传一张你自己的照片，就能让「你」来讲这篇稿子」，一个玫瑰红实心按钮「添加主播…」。底部右侧两个按钮「先不做」和灰掉不可点的「交给 Claude 做」，左侧小灰字「先添加一个主播」。$S" &
gen ui_hosts_pick "【已经有主播的状态】弹出单从上到下：标题「做成视频」；「包装风格」三张并排小卡片（第一张选中）；「比例」分段选择。然后「主播」区域：一排横向的竖长圆角卡片，每张上面是人物半身照缩略图、下面是名字和一行小灰字比例：第一张「我（职业装）· 9:16」被选中，有玫瑰红描边和右上角玫瑰红小勾；第二张「我（居家）· 16:9」；最后一张是虚线描边的「＋ 添加主播」卡片。鼠标停在第二张卡片上时右上角出现一个小的「⋯」按钮。主播区域下面一行「出镜模型」右边下拉「Wan 3.0（推荐，长镜头更稳）」。底部右侧「先不做」和玫瑰红实心主按钮「交给 Claude 做」，左侧小灰字「会在 Claude 桌面版新开一个会话，报价确认后才花积分」。$S" &
gen ui_host_add "【添加主播的弹出单】标题「添加主播」。左边是一个大的竖长照片区域，已经放进了一张虚构亚洲女性的正面半身照（自然光、背景简洁），照片下方一行小字链接「换一张」。右边从上到下：输入框「名字」里写着「我（职业装）」；一行「照片方向」右边灰字「竖图 · 适合 9:16」；一个小的提示卡片，标题「怎样的照片效果好」，三条带小勾的短句「正脸、看得清五官」「光线均匀、没有遮挡」「半身、背景简单」；一个复选框（已勾选，玫瑰红）「这是我本人，或者我已获得照片中本人的授权」。底部小灰字「照片会上传到你的 Renoise 账号，作为生成视频的参考，不花积分。」，右下角按钮「取消」和玫瑰红实心按钮「上传并保存」。$S" &
wait
